package at.hausgarten.service;
import org.json.*;
import java.util.*;

/** Real tool schemas/dispatch/quality logic. Timer persistence requires Android tests. */
public final class PixelMcpDailyTests {
    static JSONObject state()throws Exception{JSONObject value=PixelMcpWriteTests.state().put("work_session",SyntheticBusinessData.object().put("state","IDLE"));value.getJSONObject("master").put("photos",new JSONArray());return value;}
    static JSONObject start()throws Exception{return SyntheticBusinessData.object().put("request_id","timer-request-1").put("customer_id","qa_c1");}
    static JSONObject session(String status)throws Exception{return SyntheticBusinessData.object().put("id","qa_ses-fixture").put("state",status).put("customer_id","qa_c1").put("order_id","").put("work_date","2026-10-12").put("hours",5.5);}
    static JSONObject transition()throws Exception{return SyntheticBusinessData.object().put("request_id","timer-request-2").put("session_id","qa_ses-fixture");}
    public static void main(String[] ignored)throws Exception{ SyntheticBusinessData.verify();
        PixelMcpWriteTests.test("new customer history uses actual IDs",()->{JSONObject s=state();JSONObject r=new PixelMcpReadTools(()->s).call("get_customer_work_records",SyntheticBusinessData.object().put("customer_id","qa_c1"));PixelMcpWriteTests.yes(r.getJSONObject("data").getJSONArray("work_records").length()==1);});
        PixelMcpWriteTests.test("missing/invented customer IDs rejected",()->{PixelMcpReadTools t=new PixelMcpReadTools(()->state());PixelMcpWriteTests.bad(()->t.call("get_customer_work_records",SyntheticBusinessData.object()));PixelMcpWriteTests.bad(()->t.call("get_customer_work_records",SyntheticBusinessData.object().put("customer_id","qa_invented")));});
        PixelMcpWriteTests.test("quality report is read-only and billing not guessed",()->{JSONObject s=state();String old=s.toString();JSONObject r=new PixelMcpReadTools(()->s).call("get_work_record_summary",SyntheticBusinessData.object()).getJSONObject("data");PixelMcpWriteTests.yes(r.getInt("work_records")==2&&r.getInt("proven_invoiced")==0&&r.getInt("billing_unclear_or_draft")==1&&old.equals(s.toString()));});
        PixelMcpWriteTests.test("invoice evidence requires relation and noncancelled source",()->{JSONObject row=SyntheticBusinessData.object().put("id","qa_w").put("billed",0),inv=SyntheticBusinessData.object().put("id","qa_i").put("issued_at","2026-10-12").put("status","Gestellt").put("worklog_ids",new JSONArray().put("qa_w"));PixelMcpWriteTests.yes(PixelMcpBusinessTools.billing(row,new JSONArray().put(inv)).equals("proven_invoiced"));inv.put("status","Storniert");PixelMcpWriteTests.yes(PixelMcpBusinessTools.billing(row,new JSONArray().put(inv)).equals("marked_open_not_proven"));});
        PixelMcpWriteTests.test("complete summary includes more than list limit",()->{JSONObject s=state();for(int i=0;i<130;i++)s.getJSONObject("master").getJSONArray("worklogs").put(SyntheticBusinessData.object().put("id","qa_extra"+i).put("customer_id","qa_c1").put("work_date","2026-09-01").put("activity","Activity "+i).put("hours",1));PixelMcpWriteTests.yes(new PixelMcpReadTools(()->s).call("get_work_record_summary",SyntheticBusinessData.object()).getJSONObject("data").getInt("work_records")==132);});
        PixelMcpWriteTests.test("material cost maps exactly once to existing field",()->{JSONObject p=PixelMcpWriteTools.prepare("create_customer_work_record",PixelMcpWriteTests.create().put("material","3 Säcke Mulch").put("material_cost",15),state(),"cost");PixelMcpWriteTests.yes(p.getString("material").equals("3 Säcke Mulch\nMaterialkosten [EUR]: 15.00")&&!p.has("material_cost"));p.put("material_cost",16.5);PixelMcpWriteTools.applyMaterialCost(p);PixelMcpWriteTests.yes(p.getString("material").equals("3 Säcke Mulch\nMaterialkosten [EUR]: 16.50"));});
        PixelMcpWriteTests.test("negative/overprecise material cost rejected",()->{PixelMcpWriteTests.bad(()->PixelMcpWriteTools.prepare("create_customer_work_record",PixelMcpWriteTests.create().put("material_cost",-1),state(),"cost"));PixelMcpWriteTests.bad(()->PixelMcpWriteTools.prepare("create_customer_work_record",PixelMcpWriteTests.create().put("material_cost",1.001),state(),"cost"));});
        PixelMcpWriteTests.test("time calculation 8 to 14:30 minus 60 equals 5.5",()->{JSONObject p=PixelMcpWriteTools.prepare("create_customer_work_record",PixelMcpWriteTests.create().put("start_time","08:00").put("end_time","14:30").put("break_minutes",60).put("hours",5.5),state(),"hours");PixelMcpWriteTests.yes(p.getDouble("hours")==5.5);});
        PixelMcpWriteTests.test("overlapping times rejected across customers; adjacent allowed",()->{JSONObject a=SyntheticBusinessData.object().put("id","qa_a").put("work_date","2026-10-12").put("start_time","08:00").put("end_time","12:00"),b=SyntheticBusinessData.object().put("id","qa_b").put("work_date","2026-10-12").put("start_time","11:00").put("end_time","13:00");PixelMcpWriteTests.bad(()->PixelMcpBusinessTools.preventOverlap(a,new JSONArray().put(b)));b.put("start_time","12:00");PixelMcpBusinessTools.preventOverlap(a,new JSONArray().put(b));});
        for(String phase:new String[]{"queued","transferred","accepted","failed","superseded"})PixelMcpWriteTests.test("sync mapping "+phase,()->{JSONObject mapped=PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("status",phase).put("saved_locally",true),state());String expected=phase.equals("accepted")?"sync_confirmed":phase.equals("failed")?"sync_failed":phase.equals("superseded")?"sync_conflict":"sync_pending";PixelMcpWriteTests.yes(mapped.getString("sync_state").equals(expected)&&mapped.getString("local_state").equals("local_saved"));});
        PixelMcpWriteTests.test("timer start requires customer and Vienna default",()->{JSONObject p=PixelMcpSessionTools.prepare("start_work",start(),state());PixelMcpWriteTests.yes(p.getString("work_date").equals(java.time.LocalDate.now(java.time.ZoneId.of("Europe/Vienna")).toString()));PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("start_work",start().put("customer_id","qa_invented"),state()));});
        PixelMcpWriteTests.test("active/incorrect order start blocked",()->{PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("start_work",start(),state().put("work_session",session("RUNNING"))));PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("start_work",start().put("order_id","qa_o2"),state()));});
        for(String tool:PixelMcpSessionTools.NAMES)PixelMcpWriteTests.test("timer schema rejects arbitrary input "+tool,()->PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare(tool,start().put("sql","DELETE"),state())));
        PixelMcpWriteTests.test("pause resume stop typed state transitions",()->{JSONObject s=state().put("work_session",session("RUNNING"));PixelMcpSessionTools.prepare("start_break",transition(),s);PixelMcpSessionTools.prepare("stop_work",transition(),s);PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("end_break",transition(),s));s.put("work_session",session("PAUSED"));PixelMcpSessionTools.prepare("end_break",transition(),s);PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("start_break",transition(),s));});
        PixelMcpWriteTests.test("completion retains timer net hours and real customer",()->{JSONObject p=PixelMcpSessionTools.prepare("complete_work_session",transition().put("activity","Thuja pflegen").put("material_cost",15),state().put("work_session",session("STOPPED_PENDING_REVIEW")));PixelMcpWriteTests.yes(p.getDouble("hours")==5.5&&p.getString("customer_id").equals("qa_c1")&&p.getInt("billed")==0);PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("complete_work_session",transition().put("activity","Test").put("customer_id","qa_c2"),state().put("work_session",session("STOPPED_PENDING_REVIEW"))));});
        PixelMcpWriteTests.test("active session and sync overview read; writes denied without sink",()->{JSONObject s=state().put("work_session",session("PAUSED"));PixelMcpReadTools t=new PixelMcpReadTools(()->s);PixelMcpWriteTests.yes(t.call("get_active_work_session",SyntheticBusinessData.object()).getJSONObject("data").getString("state").equals("PAUSED"));t.call("get_sync_overview",SyntheticBusinessData.object());PixelMcpWriteTests.bad(()->t.call("start_work",start()));});
        PixelMcpWriteTests.test("invoice drafts dispatch with write permission; denied in read only mode",()->{Set<String> called=new HashSet<>();PixelMcpReadTools t=new PixelMcpReadTools(()->state(),new PixelMcpWriteTools.Sink(){public JSONObject execute(String n,JSONObject a)throws Exception{called.add(n);return SyntheticBusinessData.object().put("ok",true);}public JSONObject status(String id,JSONObject s){return SyntheticBusinessData.object();}});t.call("create_invoice_draft",SyntheticBusinessData.object());t.call("update_invoice_draft",SyntheticBusinessData.object());PixelMcpWriteTests.yes(called.size()==2);PixelMcpWriteTests.bad(()->new PixelMcpReadTools(()->state()).call("create_invoice_draft",SyntheticBusinessData.object()));});
        PixelMcpWriteTests.test("failed Drive retains local save and retries; acknowledgement wins",()->{JSONObject s=state().put("drive_sync_failed",true);JSONObject a=PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("status","queued").put("saved_locally",true),s);PixelMcpWriteTests.yes(a.getString("sync_state").equals("sync_failed")&&a.getBoolean("retryable"));PixelMcpWriteTests.yes(PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("status","accepted"),s).getString("sync_state").equals("sync_confirmed"));});
        PixelMcpWriteTests.test("all timer tools actually dispatch through authorised sink",()->{Set<String> called=new HashSet<>();PixelMcpReadTools t=new PixelMcpReadTools(()->state(),new PixelMcpWriteTools.Sink(){public JSONObject execute(String n,JSONObject a)throws Exception{PixelMcpWriteTools.validate(a,PixelMcpSessionTools.schema(n));called.add(n);return SyntheticBusinessData.object().put("ok",true).put("data",SyntheticBusinessData.object().put("local_state","local_saved"));}public JSONObject status(String id,JSONObject s){return SyntheticBusinessData.object();}});for(String n:PixelMcpSessionTools.NAMES){JSONObject a=n.equals("start_work")?start():transition();if(n.equals("complete_work_session")||n.equals("finish_work"))a.put("activity","Pflege");PixelMcpWriteTests.yes(t.call(n,a).getBoolean("ok"));}PixelMcpWriteTests.yes(called.size()==PixelMcpSessionTools.NAMES.length);});
        PixelMcpWriteTests.test("timer pause minutes preserved without a second subtraction",()->{JSONObject current=session("STOPPED_PENDING_REVIEW").put("break_minutes",60);JSONObject p=PixelMcpSessionTools.prepare("complete_work_session",transition().put("activity","Test"),state().put("work_session",current));PixelMcpWriteTests.yes(p.getInt("break_minutes")==60&&p.getDouble("hours")==5.5);});
        PixelMcpWriteTests.test("clock inconsistency blocks unattended completion",()->PixelMcpWriteTests.bad(()->PixelMcpSessionTools.prepare("complete_work_session",transition().put("activity","Test"),state().put("work_session",session("STOPPED_PENDING_REVIEW").put("pause_unverified",true)))));
        PixelMcpWriteTests.test("photo reads never expose inline or thumbnail base64",()->{JSONObject s=state(),photo=SyntheticBusinessData.object().put("id","qa_p1").put("customer_id","qa_c1").put("original_name","garten.jpg").put("mime_type","image/jpeg").put("storage_name","aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.jpg").put("data","data:image/jpeg;base64,VERY_SECRET_IMAGE").put("thumbnail_data","data:image/jpeg;base64,SECRET_THUMB").put("preview_base64","SECRET_PREVIEW");s.getJSONObject("master").getJSONArray("photos").put(photo);String output=new PixelMcpReadTools(()->s).call("list_photos",SyntheticBusinessData.object().put("customer_id","qa_c1")).toString();PixelMcpWriteTests.yes(!output.contains("VERY_SECRET_IMAGE")&&!output.contains("SECRET_THUMB")&&!output.contains("SECRET_PREVIEW")&&output.contains("storage_name"));});
        PixelMcpWriteTests.test("local application is not a provider delivery receipt",()->PixelMcpWriteTests.yes(PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("status","applied_on_pixel").put("uploaded_to_drive",false).put("confirmation_scope","local_only"),state()).getString("sync_state").equals("sync_pending")));
        PixelMcpWriteTests.test("legacy local test action is not awaiting Drive even after purge",()->{
            JSONObject s=state().put("drive_sync_failed",true),p=SyntheticBusinessData.object().put("id","qa_purged_work").put("_local_only",true);
            s.put("pending",new JSONArray().put(SyntheticBusinessData.object().put("client_id","qa_local_request").put("kind","worklog").put("payload",p)));
            String before=PixelMcpWriteTools.hash(s);
            JSONObject r=PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("client_id","qa_local_request").put("status","queued").put("saved_locally",true),s);
            PixelMcpWriteTests.yes(r.getString("status").equals("local_saved")&&r.getString("sync_state").equals("not_applicable")&&r.getBoolean("test_local_only"));
            PixelMcpWriteTests.yes(!r.getBoolean("retryable")&&!r.getBoolean("cloud_confirmed")&&!r.getBoolean("uploaded_to_drive")&&!r.getBoolean("provider_readback")&&!r.getBoolean("confirmed_by_app"));
            PixelMcpWriteTests.yes(PixelMcpWriteTools.hash(s).equals(before));
            JSONObject other=PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("client_id","qa_other_request").put("status","queued").put("saved_locally",true),s);
            PixelMcpWriteTests.yes(other.getString("sync_state").equals("sync_failed")&&!other.optBoolean("test_local_only"));
        });
        PixelMcpWriteTests.test("durable local receipt needs no remaining customer or journal row",()->{
            JSONObject s=state();s.getJSONObject("master").put("drive_cloud_receipts",SyntheticBusinessData.object().put("qa_local_request",SyntheticBusinessData.object().put("cloud_confirmed",true).put("applied",true)));
            JSONObject r=PixelMcpBusinessTools.sync(SyntheticBusinessData.object().put("client_id","qa_local_request").put("status","superseded").put("saved_locally",true).put("test_local_only",true),s);
            PixelMcpWriteTests.yes(r.getString("sync_state").equals("not_applicable")&&r.getString("confirmation_scope").equals("local_only")&&!r.getBoolean("cloud_confirmed"));
        });
        System.out.println("PASS total="+PixelMcpWriteTests.count+" daily MCP rules/dispatch checks; Android persistence not simulated");
    }
}
